user_prompt:
method is_bored(S: string) returns (count: int)
    requires S != null
    ensures count >= 0
    ensures count == CountBoredoms(S)

    // where CountBoredoms is a helper method to count sentences starting with "I"
    // This can be defined separately for clarity and modularity.

problem_data.canonical_solution:
import re
sentences = re.split(r'[.?!]\s*', S)
return sum(sentence[0:2] == 'I ' for sentence in sentences)
